using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioPresetStoreOperations:RefCounted
{
    private const string Root="user://audio_workspace/presets",Recovery="user://audio_workspace/preset_recovery";
    private static string Id(){using var crypto=new Crypto();return Convert.ToHexString(crypto.GenerateRandomBytes(16)).ToLowerInvariant();}
    private static string Canonical(string path)=>ProjectSettings.GlobalizePath(path).Replace('\\','/').SimplifyPath();
    private static string S(Settings d,string key)=>d.TryGetValue(key,out var value)?value.AsString():"";
    private static bool IsPreset(Resource? resource){if(resource==null)return false;var script=resource.GetScript().AsGodotObject() as Script;var expected=GD.Load<CSharpScript>("res://Workspaces/AudioWorkspace/KiwiAudioPreset.cs");while(script!=null){if(script==expected)return true;script=script.GetBaseScript();}return false;}
    public bool owned(string path){string root=Canonical(Root),absolute=Canonical(path);using var folder=DirAccess.Open(root);return folder!=null&&absolute.GetBaseDir()==root&&!folder.IsLink(absolute.GetFile())&&absolute.GetExtension()=="tres";}
    public string remove(string path,string digest){if(!owned(path)||digest.Length==0||Godot.FileAccess.GetSha256(path)!=digest)return "The preset changed or is outside the library. Refresh before removing it.";string directory=ProjectSettings.GlobalizePath(Recovery);if(DirAccess.MakeDirRecursiveAbsolute(directory)!=Error.Ok)return "Could not create the preset recovery folder.";var error=DirAccess.RenameAbsolute(ProjectSettings.GlobalizePath(path),directory.PathJoin(Id()+"_"+path.GetFile()));return error==Error.Ok?"":"Preset removal failed; the original was preserved: "+error;}
    public string rename(string path,string digest,string label,string folder)
    {
        if(!owned(path)||digest.Length==0||Godot.FileAccess.GetSha256(path)!=digest)return "The preset changed. Refresh before renaming it.";var preset=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);if(!IsPreset(preset))return "The preset is unreadable.";var copy=preset.Duplicate(false);copy.ResourcePath="";copy.Set("label",label[..Math.Min(label.Length,128)]);if(folder!="__preserve"){folder=folder.Replace('\\','/').Trim();if(folder.StartsWith('/'))folder=folder[1..];if(folder.EndsWith('/'))folder=folder[..^1];var parts=folder.Split('/');if(folder.Length>256||Array.IndexOf(parts,"..")>=0||Array.IndexOf(parts,".")>=0)return "Use a short folder label without dot segments.";copy.Set("folder",folder);}string temporary=path.GetBaseName()+".writing-"+Id()+".tres",backup=path+".rename-backup-"+Id();var error=ResourceSaver.Save(copy,temporary);if(error!=Error.Ok)return "Could not save the renamed preset. Original preserved.";if(Godot.FileAccess.GetSha256(path)!=digest){DirAccess.RemoveAbsolute(temporary);return "The preset changed while saving. Original preserved.";}error=DirAccess.RenameAbsolute(ProjectSettings.GlobalizePath(path),ProjectSettings.GlobalizePath(backup));if(error!=Error.Ok){DirAccess.RemoveAbsolute(temporary);return "Could not retain the previous preset.";}error=DirAccess.RenameAbsolute(ProjectSettings.GlobalizePath(temporary),ProjectSettings.GlobalizePath(path));if(error!=Error.Ok){DirAccess.RenameAbsolute(ProjectSettings.GlobalizePath(backup),ProjectSettings.GlobalizePath(path));return "Could not publish the renamed preset; retained backup: "+backup;}return "";
    }
    public Godot.Collections.Array<Settings> recoverable()
    {
        var result=new Godot.Collections.Array<Settings>();foreach(string root in new[]{Root,Recovery}){using var folder=DirAccess.Open(root);if(folder==null)continue;folder.ListDirBegin();string name=folder.GetNext();int visited=0;while(name.Length>0&&visited<2048){visited++;if(!folder.CurrentIsDir()&&!folder.IsLink(name)&&(root==Recovery&&name.EndsWith(".tres",StringComparison.Ordinal)||root==Root&&(name.Contains(".tags-backup-")||name.Contains(".rename-backup-"))))result.Add(new Settings{["path"]=root.PathJoin(name),["label"]=name,["digest"]=Godot.FileAccess.GetSha256(root.PathJoin(name))});name=folder.GetNext();}folder.ListDirEnd();}return result;
    }
    public string restore(Settings entry)
    {
        bool found=false;foreach(var current in recoverable())if(S(current,"path")==S(entry,"path")&&S(current,"digest")==S(entry,"digest")){found=true;break;}if(!found)return "The recovery file changed or is unavailable.";using(var file=Godot.FileAccess.Open(S(entry,"path"),Godot.FileAccess.ModeFlags.Read)){if(file==null||file.GetLength()>128UL*1024*1024)return "Preset recovery supports native files up to 128 MiB.";}DirAccess.MakeDirRecursiveAbsolute(ProjectSettings.GlobalizePath(Root));string destination=Root.PathJoin(Id()+".tres");if(DirAccess.CopyAbsolute(ProjectSettings.GlobalizePath(S(entry,"path")),ProjectSettings.GlobalizePath(destination))!=Error.Ok)return "Could not copy the recovery preset.";var preset=ResourceLoader.Load(destination,"",ResourceLoader.CacheMode.Ignore);if(!IsPreset(preset)){DirAccess.RemoveAbsolute(destination);return "The recovery file is not a readable audio preset.";}preset.Set("id",Id());preset.Set("label",preset.Get("label").AsString()+" (restored)");var error=ResourceSaver.Save(preset,destination);return error!=Error.Ok?"Could not finalize restored metadata. Recovery original retained.":"";
    }
}
